function sunTimesForDay(year, month, day) {
const rad = Math.PI / 180;
const start = Date.UTC(year, month, day);
const jan1 = Date.UTC(year, 0, 1);
const doy = Math.floor((start - jan1) / 86400000) + 1;
const gamma = (2 * Math.PI / 365) * (doy - 1 + 0.5);
const eqtime = 229.18 * (0.000075 + 0.001868 * Math.cos(gamma) - 0.032077 * Math.sin(gamma) - 0.014615 * Math.cos(2 * gamma) - 0.040849 * Math.sin(2 * gamma));
const decl = 0.006918 - 0.399912 * Math.cos(gamma) + 0.070257 * Math.sin(gamma) - 0.006758 * Math.cos(2 * gamma) + 0.000907 * Math.sin(2 * gamma) - 0.002697 * Math.cos(3 * gamma) + 0.00148 * Math.sin(3 * gamma);
const zenith = 90.833;
const cosH = (Math.cos(zenith * rad) - Math.sin(lat * rad) * Math.sin(decl)) / (Math.cos(lat * rad) * Math.cos(decl));
if (cosH > 1 || cosH < -1) {
return { sunrise: null, sunset: null };
}
const ha = Math.acos(cosH) / rad;
const toIso = (minutes) => new Date(start + Math.round(minutes * 60000)).toISOString();
return {
sunrise: toIso(720 - 4 * (lng + ha) - eqtime),
sunset: toIso(720 - 4 * (lng - ha) - eqtime),
};
}
