const pick = $('Check Perenual Cache').first().json;
const species = String(pick.species || '').trim();
const item = $input.first().json;
const norm = (v) => String(v || '').toLowerCase().replace(/\s+/g, ' ').trim();
const fail = (status, detail) => [{ json: { found: false, status, species, id: '', common_name: '', scientific_name: '', rank: 0, error_detail: String(detail || '').slice(0, 300) } }];
if (item && item.error) {
const err = item.error;
const code = String(err.httpCode || err.code || err.statusCode || '');
if (code === '429') { return fail('quota_exhausted', err.message || 'rate limited'); }
return fail('lookup_failed_' + (code || 'timeout'), err.message || 'http error');
}
const data = Array.isArray(item.data) ? item.data : [];
if (!data.length) { return fail('not_found', 'empty data[]'); }
const words = norm(species).split(' ').filter(Boolean);
const genus = words[0] || '';
const binom = words.slice(0, 2).join(' ');
let best = data[0];
let bestRank = 0;
for (const hit of data) {
const sciArr = Array.isArray(hit.scientific_name) ? hit.scientific_name.map(norm) : [norm(hit.scientific_name)];
const common = norm(hit.common_name);
let rank = 1;
if (sciArr.includes(norm(species)) || (binom && sciArr.includes(binom))) { rank = 3; }
else if (common === norm(species)) { rank = 2; }
else if (genus && (sciArr.some((s) => s.startsWith(genus + ' ')) || common.includes(genus))) { rank = 1.5; }
if (rank > bestRank) { bestRank = rank; best = hit; }
}
const sciOut = Array.isArray(best.scientific_name) ? (best.scientific_name[0] || '') : (best.scientific_name || '');
return [{ json: { found: true, status: 'ok', species, id: best.id !== undefined && best.id !== null ? best.id : '', common_name: best.common_name || '', scientific_name: sciOut, rank: bestRank, error_detail: '' } }];

