const deny = (reason, extra) => ({ json: Object.assign({ ok: false, denied: true, answer: 'I cannot answer that reliably from the available data.', answer_type: 'unavailable', needs_more_data: true, warnings: [reason], generated_at_utc: new Date().toISOString() }, extra || {}) });
if (!req.has_token) { return [deny('missing_authorization')]; }
if (item && item.error) { return [deny('token_verification_unavailable')]; }
const aud = String(item.aud || item.audience || item.issued_to || '');
const exp = Number(item.expires_in || 0);
if (aud !== '515418269010-ensbsq2skmsrsk3npg9quupqt76rboc2.apps.googleusercontent.com') { return [deny('wrong_audience')]; }
if (!(exp > 0)) { return [deny('token_expired_or_invalid')]; }
const scope = String(item.scope || '');
if (scope && scope.indexOf('spreadsheets') < 0) { return [deny('insufficient_scope')]; }
const store = $getWorkflowStaticData('global');
store.rl = store.rl || {};
const key = 'Detection:' + req.token.slice(-24);
const now = Date.now();
const windowMs = 60000;
const hits = (store.rl[key] || []).filter((t) => now - t < windowMs);
if (hits.length >= 30) { return [deny('rate_limited')]; }
hits.push(now);
store.rl[key] = hits;
return [{ json: Object.assign({}, req, { denied: false, auth_aud: aud }) }];

const req = $('Dash Detection Extract').first().json;
const rawScans = $('Dash Detection Read Scans').all().map((i) => i.json);
const rawCfg2 = $('Dash Detection Read Config').all().map((i) => i.json);
const rawEv2 = $('Dash Detection Read Events').all().map((i) => i.json);
const derrs = [].concat(rawScans, rawCfg2, rawEv2).filter((r) => r && r.error);
const dQuota = derrs.some((r) => { const h = String(r.error.httpCode || ''); const m = String(r.error.message || ''); return h === '429' || /RESOURCE_EXHAUSTED|quota|rate limit/i.test(m); });
if (dQuota) { return [{ json: { ok: false, detection: null, history: [], generated_at_utc: new Date().toISOString(), warnings: ['sheets_rate_limited'], retry_after_seconds: 60, message: 'Plant data is temporarily busy. Please try again in about a minute.' } }]; }
const scans = rawScans.filter((r) => !r.error && r.timestamp);
scans.sort((a, b) => Date.parse(a.timestamp) - Date.parse(b.timestamp));
const cfgRows = rawCfg2.filter((r) => !r.error);
const cfg = {};
for (const row of cfgRows) if (row.Key) cfg[String(row.Key).trim()] = row.Value;
const evs = rawEv2.filter((r) => !r.error && r.Timestamp);
evs.sort((a, b) => Date.parse(a.Timestamp) - Date.parse(b.Timestamp));
const last = evs.length ? evs[evs.length - 1] : null;
const nowIso = new Date().toISOString();
const driveId = (link) => { const m = String(link || '').match(/\/d\/([A-Za-z0-9_-]{10,})/); return m ? m[1] : ''; };
const idOf = (s) => 'ds-' + String(s.timestamp).replace(/[^0-9A-Za-z]/g, '');
let scan = null;
if (req.detection_id) { scan = scans.filter((s) => idOf(s) === req.detection_id)[0] || null; }
if (!scan) scan = scans.length ? scans[scans.length - 1] : null;
if (!scan) return [{ json: { ok: true, detection: null, history: [], generated_at_utc: nowIso, warnings: ['no_detections'] } }];
const parseJson = (v) => { try { return JSON.parse(v); } catch (e) { return null; } };
const yolo = parseJson(scan.yolo_opinion) || {};
const vision = parseJson(scan.vision_opinion) || {};
const plan = parseJson(scan.treatment_plan);
const label = yolo.label_simple || yolo.label || scan.judge_verdict || 'unknown';
const confidence = Number(yolo.confidence);
const verdict = String(scan.judge_verdict || '').toLowerCase();
const status = /issue|problem|disease|pest/.test(verdict) ? 'possible_issue' : /monitor/.test(verdict) ? 'monitor' : /healthy|clean|none|ok/.test(verdict) ? 'clear' : 'unknown';
const symptoms = Array.isArray(vision.suspected_issues) && vision.suspected_issues.length ? vision.suspected_issues.join('; ') : (Array.isArray(vision.symptoms_observed) ? vision.symptoms_observed.join('; ') : '');
const detail = String(scan.judge_reasoning || '').trim() || symptoms || 'no detail recorded';
const observation = (status === 'clear' ? 'The latest check found no issues: ' : 'Unverified visual hypothesis (possible issue detected): ') + detail;
let actions = [];
if (plan) {
if (Array.isArray(plan.treatment_steps)) actions = plan.treatment_steps.map(String).slice(0, 6);
else if (plan.treatment_plan) actions = Array.isArray(plan.treatment_plan) ? plan.treatment_plan.slice(0, 6) : [String(plan.treatment_plan)];
}
if (!actions.length && typeof scan.treatment_plan === 'string' && scan.treatment_plan.trim()) actions = [String(scan.treatment_plan).trim().slice(0, 300)];
const imageUrl = scan.drive_links && driveId(scan.drive_links) ? String(scan.drive_links) : null;
const imageId = driveId(scan.drive_links) || null;
const basis = ['species ' + (cfg['last_species_guess'] || 'unknown')];
if (last) basis.push('latest moisture ' + (last.MoisturePercent || 'n/a') + '%, water ' + (last.WaterTempC || 'n/a') + ' C @ ' + last.Timestamp);
const warnings = ['ai_unverified'];
if (!imageId) warnings.push('no_linked_image');
if (String(scan.treatment_plan || '').indexOf('treatment_steps') < 0) warnings.push('treatment_text_unstructured');
const detection = {
detection_id: idOf(scan),
plant_id: req.plant_id || cfg['plant_id'] || 'default',
image_id: imageId,
image_url: imageUrl,
detected_at_utc: new Date(scan.timestamp).toISOString(),
label: String(label).slice(0, 80),
confidence: isFinite(confidence) ? confidence : 0,
observation: String(observation).slice(0, 500),
status: status,
is_ai_generated: true,
is_verified: !!(scan.user_verdict && String(scan.user_verdict).trim()),
supporting_evidence: [{ source: 'DiseaseScans', id: idOf(scan), label: 'verdict ' + (scan.judge_verdict || 'unknown') + ' @ ' + scan.timestamp }],
recommended_actions: actions,
recommendation_basis: basis,
data_warnings: warnings,
resolved: /resolved|recovered|better/i.test(String(scan.treatment_outcome || ''))
};
const history = scans.slice(-5).map((s) => { const y = parseJson(s.yolo_opinion) || {}; return { detection_id: idOf(s), detected_at_utc: new Date(s.timestamp).toISOString(), label: String(y.label_simple || y.label || s.judge_verdict || 'unknown').slice(0, 60), status: /issue|problem|disease|pest/.test(String(s.judge_verdict || '').toLowerCase()) ? 'possible_issue' : /monitor/.test(String(s.judge_verdict || '').toLowerCase()) ? 'monitor' : 'clear', has_image: !!driveId(s.drive_links) }; });
return [{ json: { ok: true, detection, history, generated_at_utc: nowIso, warnings: warnings } }];
